using System.Text.Json;
using System.Text.Json.Nodes;
using Yukkuri.Simulation;

var results=new List<object>();int failures=0;
void Require(bool ok,string reason){if(!ok)throw new Exception(reason);}
void Check(string name,Action action){try{action();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failures++;results.Add(new{name,passed=false,error=e.Message});Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Tick(WorldSimulation s,double seconds){for(int n=0;n<(int)Math.Round(seconds*10);n++){s.AdvanceInteractionPresentation(.1);s.Advance(.1);}}
string Snapshot(WorldSimulation s)=>JsonSerializer.Serialize(s.State,SaveStore.JsonOptions);
WorldSimulation Reload(WorldSimulation s){SaveStore.Validate(s.State);if(args.Length>0){var store=new SaveStore(Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[0]))!,"save-fixtures",Guid.NewGuid().ToString("N")));store.Save(s.State,0);return new(store.Load(0).State);}var state=JsonSerializer.Deserialize<WorldState>(Snapshot(s),SaveStore.JsonOptions)!;SaveStore.Validate(state);return new(state);}
int Completed(Creature a)=>a.Interaction.Development.Skills.GetValueOrDefault(LifeSkill.Care)?.Completed??0;
double Care(Creature a,Creature r)=>a.Family.Peers.GetValueOrDefault(r.Id)?.CareSeconds??0;
WorldSimulation Fixture(bool ring=true)
{
    var s=WorldSimulation.CreateInteractionPlaytest(20261031);s.State.RoomObjects.Clear();s.State.PlayerX=0;s.State.PlayerZ=7;
    // Injected component preconditions: safe satiated parent, dependent child,
    // six immobile adults in a non-overlapping ring. No progress/evidence is injected.
    foreach(var c in s.State.Creatures){c.IsYoung=false;c.Body.AgeSeconds=c.InnerAgeSeconds=2000;c.Fullness=c.Energy=c.Interaction.Hydration=c.Health=100;c.Fear=c.Pain=0;c.Aggression=.08;c.Patience=.8;c.Courage=.2;c.Personality.Initialized=true;c.Personality.Kindness=.8;c.Interaction.NextAutonomyAt=10000;c.Interaction.ToyInterest=0;c.Family.NextSocialAt=c.Family.NextCareAt=10000;c.X=c.TargetX=0;c.Z=c.TargetZ=0;}
    var a=s.State.Creatures[0];var b=s.State.Creatures[1];var r=s.State.Creatures[2];
    r.IsYoung=true;r.Body.AgeSeconds=r.InnerAgeSeconds=0;r.Interaction.FootIntegrity=0;r.ParentId=r.Family.MotherId=a.Id;r.Family.Warmth=20;r.X=r.TargetX=ring?3.5:1.5;
    b.Interaction.FootIntegrity=0;b.X=b.TargetX=-6;b.Z=b.TargetZ=-6;
    if(ring)for(int k=0;k<6;k++){var block=k==0?b:JsonSerializer.Deserialize<Creature>(JsonSerializer.Serialize(b,SaveStore.JsonOptions),SaveStore.JsonOptions)!;if(k>0){block.Id="block-"+k;block.Body.Id="block-body-"+k;block.Registration.IdentityId="block-identity-"+k;block.Interaction.Accessory.Id="block-accessory-"+k;s.State.Creatures.Add(block);}block.X=block.TargetX=1.58*Math.Cos(k*Math.PI/3);block.Z=block.TargetZ=1.58*Math.Sin(k*Math.PI/3);}
    foreach(var x in s.State.Creatures)foreach(var y in s.State.Creatures.Where(y=>string.CompareOrdinal(y.Id,x.Id)>0))Require(WorldSimulation.Distance(x.X,x.Z,y.X,y.Z)>=WorldSimulation.InteractionFootprint(x)+WorldSimulation.InteractionFootprint(y),"overlapping fixture bodies");
    SaveStore.Validate(s.State);return s;
}
void Arrange(WorldSimulation s){var a=s.State.Creatures[0];var r=s.State.Creatures[2];Require(s.FamilyCareReason(a.Id,r.Id)==null,"care eligibility: "+s.FamilyCareReason(a.Id,r.Id));s.ArrangeCare(a.Id,r.Id);Require(a.Family.CareTargetId==r.Id,"arrangement failed");}
void Blocked(WorldSimulation s,bool duty=false){var a=s.State.Creatures[0];var r=s.State.Creatures[2];if(duty){a.Family.NextCareAt=1;s.SetLifeDuty(a.Id,LifeDuty.Care,r.Id);Tick(s,1);}else Arrange(s);Tick(s,9);Require(a.Family.CareTargetId==r.Id&&a.Family.CareApproachSeconds>=8&&Care(a,r)==0&&Completed(a)==0,"fixture did not produce real blocked approach without contact");}
void OpenAndContact(WorldSimulation s){var b=s.State.Creatures[1];var r=s.State.Creatures[2];Require(s.BeginInteractionGesture(b.Id,new(InteractionAction.Lift,BodyPart.Side,.1,Height:2)).Success,"real blocker lift failed");s.EndInteractionGesture();Require(s.SlideAlongGround(r.Id,1.5,0)&&Math.Abs(r.X-1.5)<.001&&Math.Abs(r.Z)<.001,"real child slide did not reach contact");}
void Finish(WorldSimulation s,double previousCare=0){var a=s.State.Creatures[0];var r=s.State.Creatures[2];for(int i=0;i<160&&Completed(a)==0;i++)Tick(s,.1);Require(Completed(a)==1&&Care(a,r)-previousCare>12,"care completion did not require actual twelve-second contact");SaveStore.Validate(s.State);}
Check("blocked approach cannot count as warm care",()=>{var s=Fixture();Blocked(s);OpenAndContact(s);Tick(s,4);var a=s.State.Creatures[0];var r=s.State.Creatures[2];Require(Completed(a)==0&&a.Family.CareTargetId==r.Id&&Care(a,r)<=4.01,"blocked time completed warm care early; actual contact="+Care(a,r));Finish(s);});
Check("stationary caregiver still earns only actual contact",()=>{var s=Fixture(false);s.State.Creatures[0].Interaction.FootIntegrity=0;Arrange(s);Tick(s,12);Require(Completed(s.State.Creatures[0])==0,"stationary care completed early");Finish(s);});
Check("fresh contact retains original twelve-second threshold",()=>{var s=Fixture(false);Arrange(s);Tick(s,12);Require(Completed(s.State.Creatures[0])==0,"completed at or below twelve seconds");Finish(s);});
Check("care duty also separates approach from warmth",()=>{var s=Fixture();Blocked(s,true);OpenAndContact(s);Tick(s,4);Require(Completed(s.State.Creatures[0])==0,"duty counted blocked approach as warmth");Finish(s);});
Check("pause and reload preserve real contact progress",()=>{var s=Fixture(false);Arrange(s);Tick(s,8);s.State.Settings.Pause=true;var before=Snapshot(s);Tick(s,5);Require(Snapshot(s)==before,"pause mutated care");s.State.Settings.Pause=false;var restored=Reload(s);Tick(s,4);Tick(restored,4);Require(Snapshot(s)==Snapshot(restored)&&Completed(restored.State.Creatures[0])==0,"reload diverged or completed early");Tick(s,.5);Tick(restored,.5);Require(Snapshot(s)==Snapshot(restored)&&Completed(restored.State.Creatures[0])==1,"reload discarded actual progress");});
Check("breaking contact does not turn prior warmth into approach or new completion",()=>{var s=Fixture(false);Arrange(s);Tick(s,8);var a=s.State.Creatures[0];var r=s.State.Creatures[2];Require(s.SlideAlongGround(r.Id,4,0)&&r.X>3.9,"child did not move away");Tick(s,.5);Require(a.Family.CareTargetId==r.Id,"old contact wrongly timed out approach");Require(s.SlideAlongGround(r.Id,a.X+1.5,a.Z),"child did not rejoin");double prior=Care(a,r);Tick(s,4);Require(Completed(a)==0,"previous contact counted toward new continuous contact");Finish(s,prior);});
Check("cancel keeps history but starts a fresh contact segment",()=>{var s=Fixture(false);Arrange(s);Tick(s,8);var a=s.State.Creatures[0];var r=s.State.Creatures[2];double prior=Care(a,r);s.EndFamilyCare(a.Id,r.Id);Require(a.Family.CareTargetId==null&&Care(a,r)==prior,"cancel erased history");Arrange(s);Tick(s,4);Require(Completed(a)==0&&Care(a,r)>prior,"new care inherited old completion or lost historical care");Finish(s,prior);});
Check("old saves default contact progress to zero without migrating mixed time",()=>{var s=Fixture(false);Arrange(s);Tick(s,8);s.State.Creatures[0].Family.CareApproachSeconds=8; // Legacy mixed timer boundary, not newly earned care.
var root=JsonNode.Parse(Snapshot(s))!;void Strip(JsonNode? node){if(node is JsonObject o){foreach(var key in o.Select(p=>p.Key).ToArray()){if(key.Equals("careContactSeconds",StringComparison.OrdinalIgnoreCase))o.Remove(key);else Strip(o[key]);}}else if(node is JsonArray a)foreach(var item in a)Strip(item);}Strip(root);var restored=new WorldSimulation(JsonSerializer.Deserialize<WorldState>(root.ToJsonString(),SaveStore.JsonOptions)!);SaveStore.Validate(restored.State);Tick(restored,4.5);Require(Completed(restored.State.Creatures[0])==0,"legacy mixed timer migrated into contact evidence");});
Check("contact timer validation follows existing nonnegative finite rule",()=>{var field=typeof(FamilyLife).GetProperty("CareContactSeconds");Require(field!=null,"dedicated contact timer absent");foreach(double invalid in new[]{-1,double.NaN,double.PositiveInfinity}){var s=Fixture(false);field!.SetValue(s.State.Creatures[0].Family,invalid);bool rejected=false;try{SaveStore.Validate(s.State);}catch(InvalidDataException){rejected=true;}Require(rejected,"invalid contact timer accepted");}var valid=Fixture(false);field!.SetValue(valid.State.Creatures[0].Family,1000001d);SaveStore.Validate(valid.State);bool nullRejected=false;try{JsonSerializer.Deserialize<FamilyLife>("{\"CareContactSeconds\":null}",SaveStore.JsonOptions);}catch(JsonException){nullRejected=true;}Require(nullRejected,"null numeric contact timer accepted");});
Check("unchanged ten-second approach timeout",()=>{var s=Fixture();Arrange(s);Tick(s,10);Require(s.State.Creatures[0].Family.CareTargetId!=null,"approach timed out before ten stalled seconds");Tick(s,.5);Require(s.State.Creatures[0].Family.CareTargetId==null&&Completed(s.State.Creatures[0])==0,"blocked approach no longer times out");});
Check("reassignment resets current segment but keeps historical care",()=>{var s=Fixture(false);Arrange(s);Tick(s,8);var a=s.State.Creatures[0];var r=s.State.Creatures[2];double history=Care(a,r);var other=s.State.Creatures[1];other.IsYoung=true;other.Body.AgeSeconds=other.InnerAgeSeconds=0;other.ParentId=other.Family.MotherId=a.Id;other.X=other.TargetX=-1.5;other.Z=other.TargetZ=0;other.Family.Warmth=20;s.ArrangeCare(a.Id,other.Id);Require(a.Family.CareTargetId==other.Id&&Care(a,r)==history,"target change failed or erased history");Tick(s,4.5);Require(Completed(a)==0&&Care(a,other)>0,"target change inherited prior contact");SaveStore.Validate(s.State);});
Check("pickup and delivery clear contact timer without losing delivery evidence",()=>{var s=Fixture(false);var a=s.State.Creatures[0];var r=s.State.Creatures[2];r.Fullness=20;var source=new RoomObject{Id="care-source",Kind=RoomObjectKind.Meal,RegionId=a.RegionId,X=0,Z=-.95,Portions=2};s.State.RoomObjects.Add(source);Arrange(s);var field=typeof(FamilyLife).GetProperty("CareContactSeconds");Require(field!=null,"dedicated timer absent");field!.SetValue(a.Family,8d); // Injected stale-phase boundary only; not earned-care evidence.
for(int n=0;n<100&&a.Family.CareParcelId==null;n++)Tick(s,.1);Require(a.Family.CareParcelId!=null&&source.Portions==1&&(double)field.GetValue(a.Family)! == 0,"pickup retained stale contact or lost portion");field.SetValue(a.Family,8d);for(int n=0;n<100&&a.Family.CareTargetId!=null;n++)Tick(s,.1);Require(a.Family.CareTargetId==null&&(double)field.GetValue(a.Family)! == 0&&Completed(a)==1&&Care(a,r)==5,"delivery timer cleanup or original five-second relationship credit changed");SaveStore.Validate(s.State);});
if(args.Length>0)File.WriteAllText(args[0],JsonSerializer.Serialize(new{failures,results},new JsonSerializerOptions{WriteIndented=true}));
Environment.ExitCode=failures==0?0:1;
